/*
# Testing module — seed real catalog data (chunk 5/6)

Upserts the actual test-case catalog (DB remaining, EDGE, APP, COMM, SOC/PALI and
SD/MEM modules, cases 240–299 of 302). ON CONFLICT upserts — safe to re-run, nothing deleted.
*/

ON CONFLICT (test_case_id) DO UPDATE SET
module_code=EXCLUDED.module_code, title=EXCLUDED.title, priority=EXCLUDED.priority,
description=EXCLUDED.description, feature=EXCLUDED.feature, sort_order=EXCLUDED.sort_order;